cat > report.js <<'EOF'
#!/usr/bin/env node
const report = require('./lib/report.js');
function render(argv) {
  const json = argv.includes('--json');
  const entries = JSON.parse(argv.find((a) => a !== '--json') || '[]');
  const result = report(entries);
  return json ? `${JSON.stringify(result)}\n` : `count=${result.count} total=${result.total}\n`;
}
if (require.main === module) process.stdout.write(render(process.argv.slice(2)));
module.exports = { render };
EOF
